package com.careerguidance.controller; import com.careerguidance.dto.response.MentorDashboardResponse; import com.careerguidance.service.MentorReviewService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/mentor") public class MentorDashboardController {private final MentorReviewService service;public MentorDashboardController(MentorReviewService s){service=s;} @GetMapping("/dashboard") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public MentorDashboardResponse dashboard(Authentication a){return service.dashboard(a);}}
